+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.dom.DomListenerRegistration;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Anchor;
+import com.vaadin.flow.component.html.Div;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.dom.DomEvent;
+import com.vaadin.flow.router.AfterNavigationEvent;
+import com.vaadin.flow.router.AfterNavigationObserver;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends Div implements BeforeLeaveObserver, AfterNavigationObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final TextField nameField = new TextField();
+    private final EmailField emailField = new EmailField();
+    private final TextField phoneField = new TextField();
+    private final TextArea messageArea = new TextArea();
+    private final Button sendButton = new Button("Send");
+    private final Grid<SendMessage> grid = new Grid<>();
+    private final Dialog dialog = new Dialog();
+
+    private ContinueNavigationAction pendingAction;
+    private DomListenerRegistration keydownRegistration;
+
+    public ContactView() {
+        nameField.setLabel("Name");
+        emailField.setLabel("Email");
+        phoneField.setLabel("Phone");
+        messageArea.setLabel("Message");
+
+        grid.addColumn(SendMessage::getName).setHeader("Name");
+        grid.addColumn(SendMessage::getEmail).setHeader("Email");
+        grid.addColumn(SendMessage::getPhone).setHeader("Phone");
+        grid.addColumn(SendMessage::getMessage).setHeader("Message");
+
+        sendButton.addClickListener(e -> send());
+
+        Button keepButton = new Button("Keep editing", e -> keepEditing());
+        Button discardButton = new Button("Discard", e -> discard());
+        dialog.add(new Paragraph("You have unsent changes. Leave anyway?"), keepButton, discardButton);
+        dialog.setModal(true);
+
+        onEdit(nameField);
+        onEdit(emailField);
+        onEdit(phoneField);
+        onEdit(messageArea);
+
+        Anchor aboutLink = new Anchor("about", "About");
+        aboutLink.getElement().addEventListener("click", e -> UI.getCurrent().navigate("about"));
+        aboutLink.getElement().addJsInitializer(
+                "this.addEventListener('click', event => event.preventDefault())");
+
+        add(new H1("Contact"), aboutLink, nameField, emailField, phoneField, messageArea, sendButton, grid);
+    }
+
+    @Override
+    public void afterNavigation(AfterNavigationEvent event) {
+        if (!isAttached()) {
+            return;
+        }
+        grid.setItems(MessageStoreHolder.current().getMessages());
+        keydownRegistration = UI.getCurrent().getElement()
+                .addEventListener("keydown", this::onKeyDown)
+                .addEventData("event.key");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        removeKeydownListener();
+        if (isDirty()) {
+            pendingAction = event.postpone();
+            if (!dialog.isOpened()) {
+                dialog.open();
+            }
+        }
+    }
+
+    private void onKeyDown(DomEvent event) {
+        if (dialog.isOpened()) {
+            return;
+        }
+        if (!event.getEventData().has("event.key")) {
+            return;
+        }
+        if ("Enter".equals(event.getEventData().get("event.key").asText())) {
+            send();
+        }
+    }
+
+    private void onEdit(TextFieldBase<?, String> field) {
+        field.addValueChangeListener(event -> {
+            if (event.isFromClient()) {
+                field.setErrorMessage(null);
+                sendButton.setEnabled(true);
+            }
+        });
+    }
+
+    private boolean isDirty() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageArea.getValue().isEmpty();
+    }
+
+    private void send() {
+        boolean valid = true;
+
+        if (nameField.getValue().isBlank()) {
+            nameField.setErrorMessage("Name is required");
+            valid = false;
+        } else {
+            nameField.setErrorMessage(null);
+        }
+
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        if (!email.isBlank() && !EMAIL_PATTERN.matcher(email).matches()) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isBlank() && phone.isBlank()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            emailField.setErrorMessage(null);
+        }
+
+        String message = messageArea.getValue();
+        if (message.isBlank()) {
+            messageArea.setErrorMessage("Message is required");
+            valid = false;
+        } else if (message.length() > MAX_MESSAGE_LENGTH) {
+            messageArea.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        } else {
+            messageArea.setErrorMessage(null);
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        MessageStore store = MessageStoreHolder.current();
+        store.add(new SendMessage(nameField.getValue(), email, phone, message));
+        grid.setItems(store.getMessages());
+
+        Notification notification = new Notification("Message sent");
+        UI.getCurrent().add(notification);
+        notification.open();
+
+        nameField.setValue("");
+        emailField.setValue("");
+        phoneField.setValue("");
+        messageArea.setValue("");
+
+        sendButton.setEnabled(false);
+    }
+
+    private void keepEditing() {
+        dialog.close();
+        if (pendingAction != null) {
+            ContinueNavigationAction action = pendingAction;
+            pendingAction = null;
+            action.cancel();
+        }
+        reattachKeydownListener();
+    }
+
+    private void discard() {
+        dialog.close();
+        nameField.setValue("");
+        emailField.setValue("");
+        phoneField.setValue("");
+        messageArea.setValue("");
+        if (pendingAction != null) {
+            ContinueNavigationAction action = pendingAction;
+            pendingAction = null;
+            action.proceed();
+        }
+    }
+
+    private void removeKeydownListener() {
+        if (keydownRegistration != null) {
+            keydownRegistration.remove();
+            keydownRegistration = null;
+        }
+    }
+
+    private void reattachKeydownListener() {
+        if (keydownRegistration == null && isAttached()) {
+            keydownRegistration = UI.getCurrent().getElement()
+                    .addEventListener("keydown", this::onKeyDown)
+                    .addEventData("event.key");
+        }
+    }
+}
