+package com.example.contact;
+
+import com.vaadin.flow.server.VaadinSession;
+
+public final class MessageStoreHolder {
+
+    private MessageStoreHolder() {
+    }
+
+    public static MessageStore current() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            return new MessageStore();
+        }
+        MessageStore store = session.getAttribute(MessageStore.class);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(MessageStore.class, store);
+        }
+        return store;
+    }
+}
