+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Anchor;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactFlowTest extends SpringBrowserlessTest {
+
+    private TextField nameField() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField emailField() {
+        return $(EmailField.class).single();
+    }
+
+    private TextField phoneField() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea messageArea() {
+        return $(TextArea.class).single();
+    }
+
+    private Button sendButton() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private Grid<SendMessage> grid() {
+        return $(Grid.class).single();
+    }
+
+    private void assertNoError(com.vaadin.flow.component.HasValidation field) {
+        String message = field.getErrorMessage();
+        assertTrue(message == null || message.isEmpty(),
+                "Expected no error message but was: " + message);
+    }
+
+    private void fillValidForm() {
+        test(nameField()).setValue("Jane Doe");
+        test(emailField()).setValue("jane.doe@example.com");
+        test(phoneField()).setValue("+1 555 0100");
+        test(messageArea()).setValue("Hello, this is a test message.");
+    }
+
+    @Test
+    void contactViewHasExpectedStructure() {
+        navigate("contact", ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue($(Anchor.class).withText("About").exists());
+
+        assertEquals("", nameField().getValue());
+        assertEquals("", emailField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageArea().getValue());
+        assertTrue(sendButton().isEnabled());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void aboutViewHasHeading() {
+        navigate("about", AboutView.class);
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void sendingValidMessageAddsRowNotifiesAndResetsForm() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+        test(sendButton()).click();
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals(1, test(grid()).size());
+        SendMessage row = test(grid()).getRow(0);
+        assertEquals("Jane Doe", row.getName());
+        assertEquals("jane.doe@example.com", row.getEmail());
+        assertEquals("+1 555 0100", row.getPhone());
+        assertEquals("Hello, this is a test message.", row.getMessage());
+
+        assertEquals("", nameField().getValue());
+        assertEquals("", emailField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageArea().getValue());
+        assertFalse(sendButton().isEnabled());
+    }
+
+    @Test
+    void sendButtonIsEnabledAgainAfterNextEdit() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+        test(sendButton()).click();
+        assertFalse(sendButton().isEnabled());
+
+        test(nameField()).setValue("Someone Else");
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void pressingEnterSendsTheForm() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+        fireShortcut(Key.ENTER);
+
+        assertTrue($(Notification.class).exists());
+        assertEquals(1, test(grid()).size());
+        assertEquals("Jane Doe", test(grid()).getRow(0).getName());
+        assertFalse(sendButton().isEnabled());
+    }
+
+    @Test
+    void emptyFormIsRejectedWithErrorsAndNothingIsSent() {
+        navigate("contact", ContactView.class);
+        test(sendButton()).click();
+
+        assertEquals("Name is required", nameField().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", emailField().getErrorMessage());
+        assertEquals("Message is required", messageArea().getErrorMessage());
+
+        assertFalse($(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void invalidEmailIsRejectedWithSpecificError() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(emailField()).setValue("not-an-email");
+        test(messageArea()).setValue("Hi");
+        test(sendButton()).click();
+
+        assertNoError(nameField());
+        assertEquals("Enter a valid e-mail address", emailField().getErrorMessage());
+        assertNoError(messageArea());
+
+        assertFalse($(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+        assertEquals("not-an-email", emailField().getValue());
+    }
+
+    @Test
+    void invalidEmailWinsOverMissingContactEvenWithPhone() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(emailField()).setValue("not-an-email");
+        test(phoneField()).setValue("+1 555 0100");
+        test(messageArea()).setValue("Hi");
+        test(sendButton()).click();
+
+        assertEquals("Enter a valid e-mail address", emailField().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToSend() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(phoneField()).setValue("+1 555 0100");
+        test(messageArea()).setValue("Hi");
+        test(sendButton()).click();
+
+        assertNoError(emailField());
+        assertEquals(1, test(grid()).size());
+        assertEquals("Jane", test(grid()).getRow(0).getName());
+    }
+
+    @Test
+    void emailAloneIsEnoughToSend() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(emailField()).setValue("jane@example.com");
+        test(messageArea()).setValue("Hi");
+        test(sendButton()).click();
+
+        assertNoError(emailField());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void messageLongerThanFiveHundredCharactersIsRejected() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(emailField()).setValue("jane@example.com");
+        test(messageArea()).setValue("x".repeat(501));
+        test(sendButton()).click();
+
+        assertEquals("Message must be at most 500 characters", messageArea().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void messageOfExactlyFiveHundredCharactersIsAccepted() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(emailField()).setValue("jane@example.com");
+        test(messageArea()).setValue("x".repeat(500));
+        test(sendButton()).click();
+
+        assertNoError(messageArea());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void newestMessageIsFirstRow() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+        test(sendButton()).click();
+
+        test(nameField()).setValue("John Smith");
+        test(emailField()).setValue("john@example.com");
+        test(messageArea()).setValue("Second message.");
+        test(sendButton()).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("John Smith", test(grid()).getRow(0).getName());
+        assertEquals("Jane Doe", test(grid()).getRow(1).getName());
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingTheView() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+        test(sendButton()).click();
+        assertEquals(1, test(grid()).size());
+
+        navigate(AboutView.class);
+        assertEquals("About", $(H1.class).single().getText());
+
+        navigate("contact", ContactView.class);
+        assertEquals(1, test(grid()).size());
+        assertEquals("Jane Doe", test(grid()).getRow(0).getName());
+    }
+
+    @Test
+    void leavingWithCleanFormDoesNotShowDialog() {
+        navigate("contact", ContactView.class);
+        navigate(AboutView.class);
+
+        assertFalse($(Dialog.class).exists());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithDirtyFormShowsDialogAndKeepEditingStays() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+
+        UI.getCurrent().navigate("about");
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertTrue(getCurrentView() instanceof ContactView);
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(dialog.isOpened());
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals("Jane Doe", nameField().getValue());
+        assertEquals("Hello, this is a test message.", messageArea().getValue());
+
+        fireShortcut(Key.ENTER);
+        assertEquals(1, test(grid()).size());
+        assertEquals("Jane Doe", test(grid()).getRow(0).getName());
+    }
+
+    @Test
+    void leavingWithDirtyFormShowsDialogAndDiscardNavigates() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+
+        UI.getCurrent().navigate("about");
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertTrue(getCurrentView() instanceof ContactView);
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertFalse(getCurrentView() instanceof ContactView);
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void aboutLinkNavigatesWithoutReload() {
+        navigate("contact", ContactView.class);
+        test($(Anchor.class).withText("About").single()).click();
+
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void aboutLinkWithDirtyFormShowsDialog() {
+        navigate("contact", ContactView.class);
+        test(messageArea()).setValue("Draft");
+
+        test($(Anchor.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertTrue(getCurrentView() instanceof ContactView);
+    }
+
+    @Test
+    void failedValidationKeepsTypedValuesInForm() {
+        navigate("contact", ContactView.class);
+        test(nameField()).setValue("Jane");
+        test(messageArea()).setValue("Hi there");
+        test(sendButton()).click();
+
+        assertEquals("Give an e-mail address or a phone number", emailField().getErrorMessage());
+        assertEquals("Jane", nameField().getValue());
+        assertEquals("Hi there", messageArea().getValue());
+        assertEquals(0, test(grid()).size());
+    }
+
+    private int columnPositionByHeader(String header) {
+        var tester = test(grid());
+        for (int i = 0; i < 10; i++) {
+            if (header.equals(tester.getHeaderCell(i))) {
+                return i;
+            }
+        }
+        throw new AssertionError("Column with header " + header + " not found");
+    }
+
+    @Test
+    void gridShowsNameAndMessageColumns() {
+        navigate("contact", ContactView.class);
+        fillValidForm();
+        test(sendButton()).click();
+
+        int nameCol = columnPositionByHeader("Name");
+        int messageCol = columnPositionByHeader("Message");
+
+        assertTrue(test(grid()).getCellText(0, nameCol).contains("Jane Doe"));
+        assertTrue(test(grid()).getCellText(0, messageCol)
+                .contains("Hello, this is a test message."));
+    }
+}
